import java.util.*; class Point{private int x,y;Point(int x,int y){this.x=x;this.y=y;}public String toString(){return "("+x+", "+y+")";}public boolean equals(Object o){return o instanceof Point p&&x==p.x&&y==p.y;}public int hashCode(){return Objects.hash(x,y);}} public class PointDriver{public static void main(String[]z){Point[] a={new Point(1,2),new Point(2,3),new Point(1,2),new Point(4,5),new Point(2,3)};Set<Point>s=new HashSet<>(Arrays.asList(a));System.out.println("Distinct: "+s.size());}}
